import os, pty, select, time, sys, signal, shutil, subprocess

def run(label, argv, inputs, delay=0.15, timeout=3.0):
    print(f"===== {label}: {' '.join(argv)} inputs={inputs!r} =====")
    pid, fd = pty.fork()
    out = bytearray()
    if pid == 0:
        os.environ['TERM'] = 'xterm-256color'
        try:
            os.execv(argv[0], argv)
        except Exception as e:
            print(e, file=sys.stderr)
            os._exit(127)
    t0 = time.time(); next_i=0; next_t=t0+delay; status=None
    try:
        while True:
            now=time.time()
            if next_i < len(inputs) and now >= next_t:
                os.write(fd, inputs[next_i:next_i+1].encode('latin1'))
                next_i += 1; next_t = now + delay
            r,_,_=select.select([fd],[],[],0.05)
            if r:
                try:
                    data=os.read(fd,4096)
                    if not data: break
                    out.extend(data)
                except OSError:
                    break
            try:
                wpid, st=os.waitpid(pid, os.WNOHANG)
                if wpid:
                    status=st; break
            except ChildProcessError:
                break
            if time.time()-t0 > timeout:
                try: os.kill(pid, signal.SIGTERM)
                except ProcessLookupError: pass
                time.sleep(0.1)
                try: os.kill(pid, signal.SIGKILL)
                except ProcessLookupError: pass
                try: os.waitpid(pid,0)
                except ChildProcessError: pass
                status='timeout'; break
    finally:
        try: os.close(fd)
        except OSError: pass
    rc = 'timeout' if status=='timeout' else (os.waitstatus_to_exitcode(status) if status is not None else '?')
    print('rc=', rc)
    s=bytes(out).decode('latin1','replace')
    print(s[:5000].replace('\x1b','^[']).replace('\r','^M').replace('\n','$\n'))
    print('--tree--')
    os.system("find /tmp/nnnpty -maxdepth 4 -printf '%y %p\\n' | sort")
    print()

