        os.execv('/workspace/executable',['/workspace/executable']+args)
    t0=time.time(); sent=False
    while True:
        if not sent and time.time()-t0>0.2:
            os.write(fd,b'q'); sent=True
        r,_,_=select.select([fd],[],[],0.05)
        if r:
            try:
                d=os.read(fd,4096)
                if not d: break
                out.extend(d)
            except OSError: break
        try:
            w,st=os.waitpid(pid,os.WNOHANG)
            if w: break
        except: break
        if time.time()-t0>2:
            try: os.kill(pid,signal.SIGKILL)
            except: pass
            break
    try: os.close(fd)
    except: pass
    s=out.decode('latin1','replace')
