typedef struct {
    char *name;
    char *path;
    struct stat st;
    int selected;
} Entry;

typedef struct {
    char **v;
    size_t n, cap;
} StrVec;

typedef struct {
    char cwd[PATH_MAX];
    Entry *e;
    int n, cap;
    int cur, offset;
    int rows, cols;
    int show_hidden;
    int detail;
    int picker;
    int null_sep;
    int no_auto_advance;
    int no_rollover;
    char sort_key;
    char *sel_file;
    char filter[256];
    int filter_on;
    char message[512];
    StrVec sel;
