typedef struct {
    char *name;
    char *path;
    struct stat st;
    int selected;
} Entry;

typedef struct {
    char **v;
    size_t n, cap;
} StrVec;

typedef struct {
    char cwd[PATH_MAX];
    Entry *e;
    int n, cap;
    int cur, offset;
    int rows, cols;
    int show_hidden;
    int detail;
    int picker;
    int null_sep;
    int no_auto_advance;
    int no_rollover;
    char sort_key;
    char *sel_file;
    char filter[256];
    int filter_on;
    char message[512];
    StrVec sel;
} App;

static struct termios orig_termios;
static int raw_enabled = 0;
static int screen_enabled = 0;

static void die_cleanup(void);

static void xprintf(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    vprintf(fmt, ap);
    va_end(ap);
}

static char *xstrdup(const char *s) {
    char *p = strdup(s ? s : "");
    if (!p) { perror("strdup"); exit(2); }
    return p;
}

static void print_help(void) { fputs(help_text, stdout); }

static void disable_raw(void) {
    if (raw_enabled) {
        tcsetattr(STDIN_FILENO, TCSAFLUSH, &orig_termios);
        raw_enabled = 0;
    }
}

static void enable_raw(void) {
    if (raw_enabled) return;
    if (tcgetattr(STDIN_FILENO, &orig_termios) == -1) return;
    struct termios raw = orig_termios;
    raw.c_lflag &= (tcflag_t)~(ECHO | ICANON | IEXTEN);
    raw.c_iflag &= (tcflag_t)~(IXON | ICRNL | INLCR);
    raw.c_oflag &= (tcflag_t)~(OPOST);
    raw.c_cc[VMIN] = 1;
    raw.c_cc[VTIME] = 0;
    if (tcsetattr(STDIN_FILENO, TCSAFLUSH, &raw) != -1) raw_enabled = 1;
}

static void screen_start(void) {
    if (screen_enabled) return;
    xprintf("\033[?1049h\033[22;0;0t\033[1;24r\033(B\033[m\033[4l\033[?7h\033[?1h\033=\033[?1006;1000h\033[?25l");
    fflush(stdout);
    screen_enabled = 1;
}

static void screen_end(void) {
    if (!screen_enabled) return;
    xprintf("\033[?1006;1000l\033[24;1H\033[?12l\033[?25h\033[?1049l\033[23;0;0t\r\033[?1l\033>");
    fflush(stdout);
    screen_enabled = 0;
}

static void die_cleanup(void) {
    screen_end();
    disable_raw();
}

static void on_signal(int sig) {
    (void)sig;
    die_cleanup();
    _exit(1);
}

static void vec_add(StrVec *sv, const char *s) {
    if (sv->n == sv->cap) {
        sv->cap = sv->cap ? sv->cap * 2 : 8;
        sv->v = realloc(sv->v, sv->cap * sizeof(char*));
        if (!sv->v) exit(2);
    }
    sv->v[sv->n++] = xstrdup(s);
}

static int vec_find(StrVec *sv, const char *s) {
    for (size_t i = 0; i < sv->n; ++i) if (strcmp(sv->v[i], s) == 0) return (int)i;
    return -1;
}

static void vec_remove(StrVec *sv, int idx) {
    if (idx < 0 || (size_t)idx >= sv->n) return;
    free(sv->v[idx]);
    for (size_t i = (size_t)idx + 1; i < sv->n; ++i) sv->v[i-1] = sv->v[i];
    sv->n--;
}

static void vec_free(StrVec *sv) {
    for (size_t i = 0; i < sv->n; ++i) free(sv->v[i]);
    free(sv->v); sv->v = NULL; sv->n = sv->cap = 0;
}

static const char *base_name(const char *p) {
    const char *s = strrchr(p, '/');
    return s ? s + 1 : p;
}

static void trim_trailing_slashes(char *p) {
    size_t n = strlen(p);
    while (n > 1 && p[n-1] == '/') p[--n] = '\0';
}

static void dir_name(const char *path, char *out, size_t outsz) {
    if (!path || !*path) { snprintf(out, outsz, "."); return; }
    char tmp[PATH_MAX];
    snprintf(tmp, sizeof(tmp), "%s", path);
    trim_trailing_slashes(tmp);
    char *s = strrchr(tmp, '/');
    if (!s) snprintf(out, outsz, ".");
    else if (s == tmp) { tmp[1] = '\0'; snprintf(out, outsz, "%s", tmp); }
    else { *s = '\0'; snprintf(out, outsz, "%s", tmp); }
}

static int is_abs(const char *p) { return p && p[0] == '/'; }

static char *expand_tilde(const char *p) {
    if (!p) return NULL;
    if (p[0] == '~' && (p[1] == '/' || p[1] == '\0')) {
        const char *home = getenv("HOME");
        if (!home) home = "/";
        char buf[PATH_MAX];
        snprintf(buf, sizeof(buf), "%s%s", home, p + 1);
        return xstrdup(buf);
    }
    return xstrdup(p);
}

static void abs_path_from(const char *base, const char *p, char *out, size_t outsz) {
    char *exp = expand_tilde(p);
    if (is_abs(exp)) snprintf(out, outsz, "%s", exp);
    else snprintf(out, outsz, "%s/%s", base && *base ? base : ".", exp);
    free(exp);
    trim_trailing_slashes(out);
}

static void join_path(const char *d, const char *n, char *out, size_t outsz) {
    if (!strcmp(d, "/")) snprintf(out, outsz, "/%s", n);
    else snprintf(out, outsz, "%s/%s", d, n);
}

static int mkdir_p(const char *path, mode_t mode) {
    if (!path || !*path) return -1;
    char tmp[PATH_MAX];
    snprintf(tmp, sizeof(tmp), "%s", path);
    trim_trailing_slashes(tmp);
    if (!strcmp(tmp, "/")) return 0;
    for (char *p = tmp + 1; *p; ++p) {
        if (*p == '/') {
            *p = '\0';
            if (mkdir(tmp, mode) == -1 && errno != EEXIST) return -1;
            *p = '/';
        }
    }
    if (mkdir(tmp, mode) == -1 && errno != EEXIST) return -1;
    return 0;
}

static int contains_ci(const char *hay, const char *needle) {
    if (!needle || !*needle) return 1;
    size_t hn = strlen(hay), nn = strlen(needle);
    if (nn > hn) return 0;
    for (size_t i = 0; i + nn <= hn; ++i) {
        size_t j = 0;
        while (j < nn && tolower((unsigned char)hay[i+j]) == tolower((unsigned char)needle[j])) j++;
        if (j == nn) return 1;
    }
    return 0;
}

static int natcmp_ci(const char *a, const char *b) {
    const unsigned char *pa = (const unsigned char*)a, *pb = (const unsigned char*)b;
    while (*pa && *pb) {
        if (isdigit(*pa) && isdigit(*pb)) {
            while (*pa == '0') pa++;
            while (*pb == '0') pb++;
            const unsigned char *sa = pa, *sb = pb;
            while (isdigit(*pa)) pa++;
            while (isdigit(*pb)) pb++;
            int lena = (int)(pa - sa), lenb = (int)(pb - sb);
            if (lena != lenb) return lena - lenb;
            int r = strncasecmp((const char*)sa, (const char*)sb, (size_t)lena);
            if (r) return r;
            continue;
        }
        int ca = tolower(*pa), cb = tolower(*pb);
        if (ca != cb) return ca - cb;
        pa++; pb++;
    }
    return (int)*pa - (int)*pb;
}

static const char *extension_of(const char *n) {
    const char *dot = strrchr(n, '.');
    if (!dot || dot == n) return "";
    return dot + 1;
}

static char g_sort_key = 'v';

static int entry_cmp(const void *av, const void *bv) {
    const Entry *a = (const Entry*)av, *b = (const Entry*)bv;
    int ad = S_ISDIR(a->st.st_mode), bd = S_ISDIR(b->st.st_mode);
    if (ad != bd) return bd - ad; /* dirs first */
    int r = 0;
    switch (g_sort_key) {
        case 's':
            if (a->st.st_size != b->st.st_size) return (a->st.st_size < b->st.st_size) ? 1 : -1;
            break;
        case 't':
            if (a->st.st_mtime != b->st.st_mtime) return (a->st.st_mtime < b->st.st_mtime) ? 1 : -1;
            break;
        case 'a':
            if (a->st.st_atime != b->st.st_atime) return (a->st.st_atime < b->st.st_atime) ? 1 : -1;
            break;
        case 'e': {
            r = strcasecmp(extension_of(a->name), extension_of(b->name));
            if (r) return r;
            break;
        }
        case 'r':
            return -natcmp_ci(a->name, b->name);
        case 'd':
        case 'v':
        default:
            break;
    }
    return natcmp_ci(a->name, b->name);
}

static void free_entries(App *app) {
    for (int i = 0; i < app->n; ++i) { free(app->e[i].name); free(app->e[i].path); }
    free(app->e); app->e = NULL; app->n = app->cap = 0;
}

static void add_entry(App *app, const char *name, const char *path, struct stat *st) {
    if (app->n == app->cap) {
        app->cap = app->cap ? app->cap * 2 : 64;
        app->e = realloc(app->e, (size_t)app->cap * sizeof(Entry));
        if (!app->e) exit(2);
    }
    app->e[app->n].name = xstrdup(name);
    app->e[app->n].path = xstrdup(path);
    app->e[app->n].st = *st;
    app->e[app->n].selected = 0;
    app->n++;
}

static void load_entries(App *app, const char *preferred) {
    int oldcur = app->cur;
    free_entries(app);
    DIR *dp = opendir(app->cwd);
    if (!dp) {
        snprintf(app->message, sizeof(app->message), "%s", strerror(errno));
        app->cur = app->offset = 0;
        return;
    }
    struct dirent *de;
    while ((de = readdir(dp))) {
        if (!strcmp(de->d_name, ".") || !strcmp(de->d_name, "..")) continue;
        if (!app->show_hidden && de->d_name[0] == '.') continue;
        if (app->filter_on && !contains_ci(de->d_name, app->filter)) continue;
        char p[PATH_MAX]; join_path(app->cwd, de->d_name, p, sizeof(p));
        struct stat st;
        if (lstat(p, &st) == -1) continue;
        add_entry(app, de->d_name, p, &st);
    }
    closedir(dp);
    g_sort_key = app->sort_key ? app->sort_key : 'v';
    qsort(app->e, (size_t)app->n, sizeof(Entry), entry_cmp);
    for (int i = 0; i < app->n; ++i) app->e[i].selected = vec_find(&app->sel, app->e[i].path) >= 0;
    if (preferred) {
        app->cur = 0;
        for (int i = 0; i < app->n; ++i) if (!strcmp(app->e[i].name, preferred)) { app->cur = i; break; }
    } else {
        app->cur = oldcur;
        if (app->cur < 0) app->cur = 0;
        if (app->cur >= app->n) app->cur = app->n - 1;
        if (app->cur < 0) app->cur = 0;
    }
    if (app->offset > app->cur) app->offset = app->cur;
}

static void get_winsz(App *app) {
    struct winsize ws;
    if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &ws) == -1 || ws.ws_row == 0) {
        app->rows = 24; app->cols = 80;
    } else {
        app->rows = ws.ws_row; app->cols = ws.ws_col;
    }
    if (app->rows < 5) app->rows = 5;
    if (app->cols < 20) app->cols = 20;
}

static void perm_string(mode_t m, char out[11]) {
    out[0] = S_ISDIR(m) ? 'd' : S_ISLNK(m) ? 'l' : '-';
    const char rwx[] = "rwx";
    for (int i = 0; i < 9; ++i) out[i+1] = (m & (1 << (8-i))) ? rwx[i%3] : '-';
    out[10] = '\0';
}

static void size_string(off_t sz, char *out, size_t n) {
    double d = (double)sz;
    const char *u = "BKMGT";
    int idx = 0;
    while (d >= 1024.0 && idx < 4) { d /= 1024.0; idx++; }
    if (idx == 0) snprintf(out, n, "%lldB", (long long)sz);
    else snprintf(out, n, "%.1f%c", d, u[idx]);
}

static void time_string(time_t t, char *out, size_t n) {
    struct tm lt;
    localtime_r(&t, &lt);
    strftime(out, n, "%Y-%m-%d %H:%M", &lt);
}

static void status_line(App *app, char *out, size_t n) {
    if (app->message[0]) { snprintf(out, n, "%s", app->message); return; }
    if (app->n <= 0) { snprintf(out, n, "0/0%s", app->show_hidden ? " H" : ""); return; }
    Entry *e = &app->e[app->cur];
    char tm[32], perm[16], sz[32], sel[32] = "";
    time_string(e->st.st_mtime, tm, sizeof(tm));
    perm_string(e->st.st_mode, perm);
    size_string(e->st.st_size, sz, sizeof(sz));
    if (app->sel.n) snprintf(sel, sizeof(sel), " +%zu", app->sel.n);
    const char *ext = extension_of(e->name);
    char extbuf[64] = "";
    if (ext && *ext && !S_ISDIR(e->st.st_mode)) snprintf(extbuf, sizeof(extbuf), " .%s", ext);
    snprintf(out, n, "%d/%d%s%s  %s %s %s%s", app->cur + 1, app->n,
             app->show_hidden ? " H" : "", sel, tm, perm, sz, extbuf);
}

static void color_for(Entry *e, int current) {
    (void)current;
    if (S_ISDIR(e->st.st_mode)) xprintf("\033[1;38;5;39m");
    else if (e->st.st_mode & (S_IXUSR|S_IXGRP|S_IXOTH)) xprintf("\033[38;5;46m");
    else xprintf("\033[38;5;196m");
}

static void render(App *app) {
    get_winsz(app);
    int maxlines = app->rows - 3;
    if (maxlines < 1) maxlines = 1;
    if (app->cur < app->offset) app->offset = app->cur;
    if (app->cur >= app->offset + maxlines) app->offset = app->cur - maxlines + 1;
    if (app->offset < 0) app->offset = 0;

    xprintf("\033[39;49m\033(B\033[m\033[H\033[2J");
    xprintf("\033[0;1;7m\033[34m1\033[39m\033(B\033[m 2 3 4 5 6 7 8 ");
    xprintf("\033[0;4m\033[34m%s\033[39m\033(B\033[m", app->cwd);
    for (int line = 0; line < maxlines; ++line) {
        int idx = app->offset + line;
        int row = 3 + line;
        xprintf("\033[%d;1H\033[K", row);
        if (idx >= app->n) continue;
        Entry *e = &app->e[idx];
        int cur = (idx == app->cur);
        if (app->detail) {
            char tm[32], sz[32];
            time_string(e->st.st_mtime, tm, sizeof(tm));
            size_string(e->st.st_size, sz, sizeof(sz));
            if (cur) xprintf("\033[0;1m>"); else xprintf(" ");
            xprintf("\033[38;5;247m%s  %03o %8s \033[39m ", tm, (unsigned)(e->st.st_mode & 0777), sz);
            if (cur) xprintf("\033[7m");
            color_for(e, cur);
            xprintf("%s%s", e->selected ? "+" : "", e->name);
            if (S_ISDIR(e->st.st_mode)) xprintf("/");
            else if (e->st.st_mode & (S_IXUSR|S_IXGRP|S_IXOTH)) xprintf("*");
            xprintf("\033[39m\033(B\033[m");
        } else {
            if (cur) xprintf("\033[0;1;7m");
            xprintf("%c", e->selected ? '+' : ' ');
            color_for(e, cur);
            xprintf("%s", e->name);
            xprintf("\033[39m\033(B\033[m");
            if (cur) xprintf("\033[0;1;7m");
            if (S_ISDIR(e->st.st_mode)) xprintf("/");
            else if (e->st.st_mode & (S_IXUSR|S_IXGRP|S_IXOTH)) xprintf("*");
            xprintf("\033[39m\033(B\033[m");
        }
    }
    char st[512]; status_line(app, st, sizeof(st));
    xprintf("\033[%d;1H\033[K\033[34m%s\033[39m\033(B\033[m", app->rows, st);
    if (app->n > 0) xprintf("\033[%d;1H", 3 + (app->cur - app->offset));
    fflush(stdout);
    app->message[0] = '\0';
}

#define KEY_UP 1001
#define KEY_DOWN 1002
#define KEY_LEFT 1003
#define KEY_RIGHT 1004
#define KEY_HOME 1005
#define KEY_END 1006

static int read_byte_timeout(int timeout_ms) {
    unsigned char c;
    fd_set rfds; FD_ZERO(&rfds); FD_SET(STDIN_FILENO, &rfds);
    struct timeval tv;
    tv.tv_sec = timeout_ms / 1000; tv.tv_usec = (timeout_ms % 1000) * 1000;
    int r = select(STDIN_FILENO + 1, &rfds, NULL, NULL, &tv);
    if (r > 0 && read(STDIN_FILENO, &c, 1) == 1) return c;
    return -1;
}

static int read_key(void) {
    unsigned char c;
    ssize_t n = read(STDIN_FILENO, &c, 1);
    if (n <= 0) return -1;
    if (c == 27) {
        int c1 = read_byte_timeout(30);
        if (c1 == '[') {
            int c2 = read_byte_timeout(30);
            if (c2 == 'A') return KEY_UP;
            if (c2 == 'B') return KEY_DOWN;
            if (c2 == 'C') return KEY_RIGHT;
            if (c2 == 'D') return KEY_LEFT;
            if (c2 == 'H') return KEY_HOME;
            if (c2 == 'F') return KEY_END;
        }
        return 27;
    }
    return c;
}

static void move_down(App *app) {
    if (app->n <= 0) return;
    if (app->cur < app->n - 1) app->cur++;
    else if (!app->no_rollover) app->cur = 0;
}

static void move_up(App *app) {
    if (app->n <= 0) return;
    if (app->cur > 0) app->cur--;
    else if (!app->no_rollover) app->cur = app->n - 1;
}

static void change_dir(App *app, const char *path, const char *preferred) {
    char real[PATH_MAX];
    if (realpath(path, real)) snprintf(app->cwd, sizeof(app->cwd), "%s", real);
    else snprintf(app->cwd, sizeof(app->cwd), "%s", path);
    chdir(app->cwd);
    app->filter_on = 0; app->filter[0] = '\0';
    app->offset = 0;
    load_entries(app, preferred);
}

static int prompt_line(App *app, const char *prompt, const char *initial, char *out, size_t outsz) {
    char buf[PATH_MAX];
    snprintf(buf, sizeof(buf), "%s", initial ? initial : "");
    size_t len = strlen(buf);
    while (1) {
        xprintf("\033[%d;1H\033[K\033[34m%s%s  \b\b\033[39m\033(B\033[m", app->rows, prompt, buf);
        xprintf("\033[?12l\033[?25h");
        fflush(stdout);
        int k = read_key();
        if (k == '\r' || k == '\n') {
            snprintf(out, outsz, "%s", buf);
            xprintf("\033[?25l");
            return 1;
        }
        if (k == 27 || k == 3) { xprintf("\033[?25l"); return 0; }
        if (k == 127 || k == 8) { if (len) buf[--len] = '\0'; continue; }
        if (k >= 32 && k < 127 && len + 1 < sizeof(buf)) { buf[len++] = (char)k; buf[len] = '\0'; }
    }
}

static void create_path(App *app, const char *name) {
    if (!name || !*name) return;
    char p[PATH_MAX]; join_path(app->cwd, name, p, sizeof(p));
    size_t n = strlen(p);
    if (n && p[n-1] == '/') {
        if (mkdir_p(p, 0777) == -1) snprintf(app->message, sizeof(app->message), "%s", strerror(errno));
    } else {
        char parent[PATH_MAX]; dir_name(p, parent, sizeof(parent));
        if (mkdir_p(parent, 0777) == -1) { snprintf(app->message, sizeof(app->message), "%s", strerror(errno)); return; }
        int fd = open(p, O_CREAT | O_EXCL | O_WRONLY, 0600);
        if (fd == -1) snprintf(app->message, sizeof(app->message), "%s", strerror(errno));
        else close(fd);
    }
    load_entries(app, base_name(name));
}

static void toggle_select(App *app) {
    if (app->n <= 0) return;
    Entry *e = &app->e[app->cur];
    int idx = vec_find(&app->sel, e->path);
    if (idx >= 0) { vec_remove(&app->sel, idx); e->selected = 0; }
    else { vec_add(&app->sel, e->path); e->selected = 1; }
    if (!app->no_auto_advance) move_down(app);
}

static void select_all(App *app) {
    for (int i = 0; i < app->n; ++i) if (vec_find(&app->sel, app->e[i].path) < 0) vec_add(&app->sel, app->e[i].path);
    for (int i = 0; i < app->n; ++i) app->e[i].selected = 1;
}

static void invert_selection(App *app) {
    for (int i = 0; i < app->n; ++i) {
        int idx = vec_find(&app->sel, app->e[i].path);
        if (idx >= 0) vec_remove(&app->sel, idx);
        else vec_add(&app->sel, app->e[i].path);
    }
    for (int i = 0; i < app->n; ++i) app->e[i].selected = vec_find(&app->sel, app->e[i].path) >= 0;
}

static void do_filter(App *app) {
    char out[256];
    char initial[256] = "";
    if (app->filter_on) snprintf(initial, sizeof(initial), "%s", app->filter);
    xprintf("\033[%d;64H\033[34m  str [/], ic [:]", app->rows - 1);
    if (prompt_line(app, "/", initial, out, sizeof(out))) {
        snprintf(app->filter, sizeof(app->filter), "%s", out);
        app->filter_on = app->filter[0] != '\0';
        app->cur = app->offset = 0;
        load_entries(app, NULL);
    } else {
        /* nnn keeps the typed filter when leaving the prompt with Esc. */
        snprintf(app->filter, sizeof(app->filter), "%s", out[0] ? out : initial);
        app->filter_on = app->filter[0] != '\0';
        load_entries(app, NULL);
    }
}

static void show_interactive_help(App *app, int *quit) {
    screen_end();
    xprintf("%s", interactive_help);
    xprintf("CONTEXTS\r\n 1* %s\r\n\r\n", app->cwd);
    xprintf("VOLUME: avail:559.406G used:440.104G size:999.512G\r\n\r\n");
    const char *home = getenv("HOME"); if (!home) home = "/home/agent";
    xprintf("SELECTION FILE: %s/.config/nnn/.selection\r\n\r\n", home);
    xprintf("v5.2\r\nBSD 2-Clause\r\nhttps://github.com/jarun/nnn\r\n");
    fflush(stdout);
    int k = read_key();
    if (k == 'q' || k == 'Q' || k == 17) *quit = 1;
    screen_start();
}

static void open_current(App *app) {
    if (app->n <= 0) return;
    Entry *e = &app->e[app->cur];
    if (S_ISDIR(e->st.st_mode)) change_dir(app, e->path, NULL);
    else {
        /* The real program launches an opener. In this compact clone, file open is non-destructive. */
        snprintf(app->message, sizeof(app->message), "%s", e->name);
    }
}

static void parent_dir(App *app) {
    char old[NAME_MAX + 1];
    snprintf(old, sizeof(old), "%s", base_name(app->cwd));
    if (!strcmp(app->cwd, "/")) return;
    char parent[PATH_MAX]; dir_name(app->cwd, parent, sizeof(parent));
    change_dir(app, parent, old);
}

static void write_selection(App *app) {
    if (!app->picker || app->sel.n == 0 || !app->sel_file) return;
    FILE *fp = NULL;
    int to_stdout = strcmp(app->sel_file, "-") == 0;
    if (to_stdout) fp = stdout;
    else fp = fopen(app->sel_file, "w");
    if (!fp) return;
    for (size_t i = 0; i < app->sel.n; ++i) {
        fputs(app->sel.v[i], fp);
        fputc(app->null_sep ? '\0' : '\n', fp);
    }
    if (!to_stdout) fclose(fp);
    else fflush(fp);
}

static char *parse_key_map(const char *env, char key, int *format_bad) {
    *format_bad = 0;
    if (!env || !*env) return NULL;
    char *copy = xstrdup(env), *save = NULL, *tok;
    char *result = NULL;
    for (tok = strtok_r(copy, ";", &save); tok; tok = strtok_r(NULL, ";", &save)) {
        if (strlen(tok) < 3 || tok[1] != ':') { *format_bad = 1; continue; }
        if (tok[0] == key) { result = xstrdup(tok + 2); break; }
    }
    free(copy);
    return result;
}

static void non_tty_hang(void) {
    fprintf(stderr, "0 entries\n");
    fflush(stderr);
    for (;;) pause();
}

static void start_from_path(App *app, const char *path_arg, char *pending_create, size_t pcsz, const char *preferred_file) {
    pending_create[0] = '\0';
    char base[PATH_MAX];
    if (!path_arg) {
        const char *pwd = getenv("PWD");
        if (pwd && *pwd) {
            if (chdir(pwd) == -1) {
                snprintf(app->message, sizeof(app->message), "%s", strerror(errno));
                snprintf(app->cwd, sizeof(app->cwd), "/");
                chdir("/");
            } else {
                char real[PATH_MAX];
                if (realpath(pwd, real)) snprintf(app->cwd, sizeof(app->cwd), "%s", real);
                else snprintf(app->cwd, sizeof(app->cwd), "%s", pwd);
            }
        } else {
            if (!getcwd(app->cwd, sizeof(app->cwd))) snprintf(app->cwd, sizeof(app->cwd), "/");
        }
        load_entries(app, preferred_file);
        return;
    }

    if (!getcwd(base, sizeof(base))) snprintf(base, sizeof(base), ".");
    const char *pwd = getenv("PWD");
    if (pwd && *pwd) snprintf(base, sizeof(base), "%s", pwd);

    int slash_end = 0;
    size_t plen = strlen(path_arg);
    if (plen && path_arg[plen-1] == '/') slash_end = 1;

    char abs[PATH_MAX];
    abs_path_from(base, path_arg, abs, sizeof(abs));
    struct stat st;
    if (stat(abs, &st) == 0) {
        if (S_ISDIR(st.st_mode)) change_dir(app, abs, NULL);
        else {
            char parent[PATH_MAX]; dir_name(abs, parent, sizeof(parent));
            change_dir(app, parent, base_name(abs));
        }
        return;
    }

    if (slash_end) {
        if (mkdir_p(abs, 0777) == -1) snprintf(app->message, sizeof(app->message), "%s", strerror(errno));
        change_dir(app, abs, NULL);
        return;
    }

    char parent[PATH_MAX]; dir_name(abs, parent, sizeof(parent));
    mkdir_p(parent, 0777);
    change_dir(app, parent, NULL);
    snprintf(pending_create, pcsz, "%s", base_name(abs));
}

int main(int argc, char **argv) {
    App app;
    memset(&app, 0, sizeof(app));
    app.sort_key = 'v';

    char *path_arg = NULL;
    char *bookmark_arg = NULL;
    char *plugin_arg = NULL;
    int opt;

    /* GNU getopt permutation matches the observed option handling. */
    while ((opt = getopt(argc, argv, "aAb:BcCdDeEfF:gHiJKnNoOp:P:QrRs:St:T:uUVxz0h")) != -1) {
        switch (opt) {
            case 'h': print_help(); return 0;
            case 'V': puts(VERSION); return 0;
            case 'K': return 0;
            case 'F': {
                int v = atoi(optarg);
                if (v < 0 || v > 1) return 1;
                break;
            }
            case 'b': bookmark_arg = optarg; break;
            case 'P': plugin_arg = optarg; break;
            case 'p': app.picker = 1; app.sel_file = optarg; break;
            case '0': app.null_sep = 1; break;
            case 'H': app.show_hidden = 1; break;
            case 'd': app.detail = 1; break;
            case 'J': app.no_auto_advance = 1; break;
            case 'R': app.no_rollover = 1; break;
            case 'T': if (optarg && *optarg) app.sort_key = *optarg; break;
            case '?': print_help(); return 1;
            default: break;
        }
    }
    if (optind < argc) path_arg = argv[optind];

    if (!isatty(STDIN_FILENO) || !isatty(STDOUT_FILENO)) non_tty_hang();

    if (bookmark_arg) {
        int bad = 0;
        char *p = parse_key_map(getenv("NNN_BMS"), bookmark_arg[0], &bad);
        if (bad && !p) { fputs("NNN_BMS\n", stdout); return 1; }
        if (!p) { fputs("invalid key\n", stdout); return 1; }
        path_arg = p;
        /* p intentionally lives until after startup. */
    }

    atexit(die_cleanup);
    signal(SIGINT, on_signal);
    signal(SIGTERM, on_signal);
    enable_raw();
    screen_start();

    char pending_create[PATH_MAX];
    start_from_path(&app, path_arg, pending_create, sizeof(pending_create), NULL);
    if (plugin_arg) {
        int bad = 0;
        char *p = parse_key_map(getenv("NNN_PLUG"), plugin_arg[0], &bad);
        if (!p || bad) snprintf(app.message, sizeof(app.message), "invalid key");
        free(p);
    }

    load_entries(&app, NULL);
    render(&app);

    if (pending_create[0]) {
        char name[PATH_MAX];
        if (prompt_line(&app, "[path/]name: ", pending_create, name, sizeof(name))) create_path(&app, name);
        render(&app);
    }

    int quit = 0;
    while (!quit) {
        int k = read_key();
        if (k < 0) continue;
        switch (k) {
            case 'q': case 'Q': case 17: quit = 1; break;
            case 'j': case KEY_DOWN: case 14: move_down(&app); break;
            case 'k': case KEY_UP: case 16: move_up(&app); break;
            case 'g': case 1: app.cur = 0; break;
            case 'G': case 5: if (app.n > 0) app.cur = app.n - 1; break;
            case 'h': case KEY_LEFT: parent_dir(&app); break;
            case 'l': case KEY_RIGHT: case '\r': case '\n': open_current(&app); break;
            case ' ': case '+': toggle_select(&app); break;
            case 'a': select_all(&app); break;
            case 'A': invert_selection(&app); break;
            case '.': app.show_hidden = !app.show_hidden; load_entries(&app, NULL); break;
            case 'd': app.detail = !app.detail; break;
            case '/': do_filter(&app); break;
            case 12: load_entries(&app, NULL); break;
            case 'n': {
                char name[PATH_MAX];
                if (prompt_line(&app, "[path/]name: ", "", name, sizeof(name))) create_path(&app, name);
                break;
            }
            case '?': show_interactive_help(&app, &quit); break;
            default: break;
        }
        if (!quit) render(&app);
    }

    screen_end();
    disable_raw();
    write_selection(&app);
    free_entries(&app);
    vec_free(&app.sel);
    return 0;
}
